package org.mattshoe.mtg.core

/** One format's ban list: its name, a line saying what the format is, and the cards. */
data class BanList(val format: String, val about: String, val cards: List<DeckCard>)

/**
 * Every format's banned cards, for the Guide.
 *
 * Matt: "add a guide section below game Changers for banned cards.
 * start with Commander at the top, then standard, then whatever order
 * makes sense". After Standard the formats go from the smallest card
 * pool to the biggest, Pioneer, Modern, Legacy, Vintage, and Pauper
 * last because it is the odd one out, commons from any set.
 *
 * Written down here, like [GameChangers], as Scryfall's `banned:<format>`
 * gave them on 2026-10-14, one printing each so a row and the carousel
 * have art. Vintage's restricted list is not here: restricted is one
 * copy allowed, not none. When Wizards change a list, this changes.
 */
object Banned {

    /** The line over the lists, the same on both shells. */
    const val ABOUT = "What each format will not let you play, one list per format. Tap a card to see it."

    /** The heading's count: how many cards a format bans. */
    fun count(list: BanList): String = list.cards.size.toString()

    val lists: List<BanList> by lazy {
        listOf(
            ban("Commander", "Wizards' list for Commander. Every ante card and every Conspiracy is on it too.", commander()),
            ban("Standard", "The last few years of sets. A card banned here usually comes off when its set rotates out.", standard()),
            ban("Pioneer", "Every set from Return to Ravnica on.", pioneer()),
            ban("Modern", "Every set from Eighth Edition on, and the Modern Horizons sets.", modern()),
            ban("Legacy", "Every card ever printed, apart from these.", legacy()),
            ban("Vintage", "Every card ever printed. Most of its strongest cards are restricted to one copy rather than banned.", vintage()),
            ban("Pauper", "Commons only, from any set.", pauper()),
        )
    }

    /** Alphabetical, in any capitals, which is not quite the order Scryfall gives them in. */
    private fun ban(format: String, about: String, cards: List<DeckCard>) = BanList(format, about, cards.sortedBy { it.name.lowercase() })

    /** Every row in the order the page draws them, so the carousel's next is the next row down. */
    val pageOrder: List<DeckCard> by lazy { lists.flatMap { it.cards } }

    // One function per format, so no one method holds all 527 rows.

